                                                                                                                                                                            'use std::io;\nuse std::collections::HashMap;\n\nfn main() {\n    let mut input = String::new();\n    io::stdin().read_line(&mut input).unwrap();\n    let s = input.trim();\n    let mut freq = HashMap::new();\n    for c in s.chars() {\n        *freq.entry(c).or_insert(0) += 1;\n    }\n    for c in s.chars() {\n        if let Some(&count) = freq.get(&c) {\n            if count == 1 {\n                println!("{}", c);\n                return;\n            }\n        }\n    }\n    println!("-");\n}',
