                                                                                                                                                                            'use std::io;\nuse std::io::BufRead;\n\nfn main() {\n    let stdin = io::stdin();\n    let mut lines = stdin.lock().lines();\n    let n: usize = lines.next().unwrap().unwrap().trim().parse().unwrap();\n    let nums_line = lines.next().unwrap().unwrap();\n    let mut arr: Vec<i32> = nums_line.split_whitespace().map(|x| x.parse().unwrap()).collect();\n    let mut steps = 0;\n    let mut swapped;\n    for i in 0..n {\n        swapped = false;\n        for j in 0..(n - i - 1) {\n            if arr[j] > arr[j + 1] {\n                arr.swap(j, j + 1);\n                steps += 1;\n                swapped = true;\n            }\n        }\n        if !swapped { break; }\n    }\n    println!("{}", steps);\n}',
